     1→import {ResponseOutgoing} from "@lodestar/reqresp";
     2→import {computeEpochAtSlot} from "@lodestar/state-transition";
     3→import {ColumnIndex} from "@lodestar/types";
     4→import {toRootHex} from "@lodestar/utils";
     5→import {IBeaconChain} from "../../../chain/index.js";
     6→import {IBeaconDb} from "../../../db/index.js";
     7→import {DataColumnSidecarsByRootRequest} from "../../../util/types.js";
     8→import {
     9→  handleColumnSidecarUnavailability,
    10→  validateRequestedDataColumns,
    11→} from "../utils/dataColumnResponseValidation.js";
    12→
    13→export async function* onDataColumnSidecarsByRoot(
    14→  requestBody: DataColumnSidecarsByRootRequest,
    15→  chain: IBeaconChain,
    16→  db: IBeaconDb
    17→): AsyncIterable<ResponseOutgoing> {
    18→  // SPEC: minimum_request_epoch = max(current_epoch - MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS, FULU_FORK_EPOCH)
    19→  const currentEpoch = chain.clock.currentEpoch;
    20→  const minimumRequestEpoch = Math.max(
    21→    currentEpoch - chain.config.MIN_EPOCHS_FOR_DATA_COLUMN_SIDECARS_REQUESTS,
    22→    chain.config.FULU_FORK_EPOCH
    23→  );
    24→
    25→  for (const dataColumnsByRootIdentifier of requestBody) {
    26→    const {blockRoot, columns: requestedColumns} = dataColumnsByRootIdentifier;
    27→    const availableColumns = validateRequestedDataColumns(chain, requestedColumns);
    28→    if (availableColumns.length === 0) {
    29→      return;
    30→    }
